List<string> fila = [];
string? linha = Console.ReadLine();
while (linha != null && linha != "fim")
{
    if (linha == "rede" || linha == "conta")
    {
        fila.Add(linha);
    }
    linha = Console.ReadLine();
}
int redes = 0;
int contas = 0;
foreach (string categoria in fila)
{
    if (categoria == "rede")
    {
        redes = redes + 1;
    }
    else
    {
        contas = contas + 1;
    }
}
Console.WriteLine("Total " + fila.Count);
Console.WriteLine("Rede " + redes);
Console.WriteLine("Conta " + contas);
